/**
 * Credits for the dish photos in public/food/<id>-<width>.<avif|webp>.
 * dishImages.json is generated by scripts/fetch-dish-images.ts; photos are
 * from Wikimedia Commons, cropped to 4:3 and resized by us.
 */
import credits from './dishImages.json';

export interface DishImage {
  id: string;
  /** Intrinsic size of the largest variant (all variants are 4:3). */
  width: number;
  height: number;
  alt: string;
  author: string;
  license: string;
  licenseUrl: string | null;
  /** The Commons file page. */
  sourceUrl: string;
  /** Changes we made, as CC BY/BY-SA ask us to say. */
  modified: string;
}

export const DISH_IMAGE_WIDTHS = [320, 640] as const;
export const DISH_IMAGE_FORMATS = ['avif', 'webp'] as const;

export const DISH_IMAGES: readonly DishImage[] = credits;

export const dishImage = (dishId: string) => DISH_IMAGES.find((image) => image.id === dishId);
